"""Actual local passages generated by the paper's bond-deleting trace.

Use finite square G, protected boundary layer S, U/X initial domains, and
follow admissible stopped trails. Capture U departures with all actual tip
statuses, missing bonds, original pins and shared conditioned outside spins.
"""
import argparse, itertools as it, time
from concurrent.futures import ProcessPoolExecutor, as_completed
from common import *
from geometry import DIRECTIONS, canonical_record, parse_pattern, edge, F
from passage_check import (new_stats,merge,one_site,record_mean,evaluate_graph,
                           passage_identity,reduce_numeric)

BOX=12

def make_records(count,seed):
    rng=np.random.default_rng(seed);records=[];trails=steps=0;keys=set();failures=[]
    cat=json.loads(CATALOGUE.read_text());cat_keys={canonical_record(*parse_pattern(p)):p['pid'] for p in cat}
    index={(i,j):n for n,(i,j) in enumerate(it.product(range(-BOX,BOX+1),repeat=2))}
    positions=list(index);interior=[p for p in positions if max(map(abs,p))<=BOX-2]
    def inside(p):return max(map(abs,p))<=BOX
    def capture(status,masks,y,back,out_dir):
        forward=tuple(-d for d in DIRECTIONS[back]);right=(forward[1],-forward[0])
        def global_site(x):return (y[0]+right[0]*x[0]+forward[0]*x[1],y[1]+right[1]*x[0]+forward[1]*x[1])
        def local_site(p):
            d=(p[0]-y[0],p[1]-y[1]);return (d[0]*right[0]+d[1]*right[1],d[0]*forward[0]+d[1]*forward[1])
        def present(p,q):
            if not inside(q):return False
            if status[index[p]]==2 or status[index[q]]==2:return False
            d=(q[0]-p[0],q[1]-p[1]);j=DIRECTIONS.index(d)
            return bool(masks[index[p]]&(1<<j) and masks[index[q]]&(1<<((j+2)%4)))
        def request(p,q):
            if not inside(q):
                assert status[index[p]]==0
                return ['pin',p,q]
            if present(p,q):return ['spin',q,int(status[index[q]])]
            return ['zero']
        out=local_site((y[0]+DIRECTIONS[out_dir][0],y[1]+DIRECTIONS[out_dir][1]))
        non_tips={x:global_site(x) for x in RING};g={};bonds=set();cover=set()
        for x,p in non_tips.items():
            st=int(status[index[p]])
            if st==2:continue
            g[x]=dict(law='u' if st==0 else 'd',mark=int(x in NEIGHBOURS),out=int(x==out),requests=[])
        for x,p in non_tips.items():
            if x not in g:continue
            for j,d in enumerate(DIRECTIONS):
                q=(p[0]+d[0],p[1]+d[1]);xx=local_site(q)
                if xx==ORIGIN and present(p,q):cover.add(edge(x,xx))
                if xx in non_tips and present(p,q):bonds.add(edge(x,xx));cover.add(edge(x,xx))
                if xx in TIPS and masks[index[p]]&(1<<j):
                    cover.add(edge(x,xx));actual=present(p,q)
                    reqs=[]
                    if actual:
                        for dd in DIRECTIONS:
                            z=(q[0]+dd[0],q[1]+dd[1])
                            if z!=p:reqs.append(request(q,z))
                    g[x]['requests'].append(dict(kind='tip',law=('u' if status[index[q]]==0 else 'd') if actual else 'x',requests=reqs))
        for x,v in g.items():
            if x in CORNERS:
                p=non_tips[x];capacity=2 if v['law']=='u' else 2-sum(x in b for b in bonds)
                reqs=[]
                for d in DIRECTIONS:
                    q=(p[0]+d[0],p[1]+d[1]);xx=local_site(q)
                    if abs(xx[0])+abs(xx[1])==3:
                        r=request(p,q)
                        if r[0]!='zero':reqs.append(r)
                assert len(reqs)<=capacity
                reqs += [['zero']]*(capacity-len(reqs))
                v['requests'] += [dict(kind='field',request=r) for r in reqs]
            v['tiponly_d']=(v['law']=='d' and v['mark'] and any(r['kind']=='tip' for r in v['requests']))
        live={x for b in cover for x in b}
        kinds={x:v['law'] for x,v in g.items() if x in live}
        key=canonical_record(kinds,cover,out)
        if key not in cat_keys:failures.append(dict(site=y,back=back,out=out,kinds=str(kinds),bonds=str(cover)))
        else:keys.add(cat_keys[key])
        return dict(pid=100000+len(records),catalogue_pid=cat_keys.get(key),site=y,incoming=forward,out=out,
                    graph={str(x):v for x,v in g.items()},edges=list(bonds),
                    local_status_kept={str(x):[int(status[index[p]]),int(masks[index[p]])] for x,p in non_tips.items()})
    while len(records)<count:
        trails+=1;status=np.zeros(len(positions),dtype=np.int8);masks=np.full(len(positions),15,dtype=np.int8)
        for p in interior:
            if rng.random()<.075:status[index[p]]=2;masks[index[p]]=0
        candidates=[]
        for p in interior:
            if status[index[p]]:continue
            backs=[j for j,d in enumerate(DIRECTIONS) if status[index[(p[0]+d[0],p[1]+d[1])]]==2]
            if backs:candidates.append((p,backs))
        if not candidates:continue
        y,backs=candidates[int(rng.integers(len(candidates)))];back=int(rng.choice(backs));masks[index[y]] &= ~(1<<back)
        for turn in range(4*len(positions)):
            if max(map(abs,y))>=BOX-1:break # First hit of protected S.
            choices=[]
            for j,d in enumerate(DIRECTIONS):
                q=(y[0]+d[0],y[1]+d[1])
                if status[index[q]]!=2 and masks[index[y]]&(1<<j) and masks[index[q]]&(1<<((j+2)%4)):choices.append(j)
            if not choices:break
            j=int(rng.choice(choices));steps+=1
            if status[index[y]]==0:
                records.append(capture(status,masks,y,back,j))
                if len(records)==count:break
            d=DIRECTIONS[j];q=(y[0]+d[0],y[1]+d[1]);idx=index[y]
            if status[idx]==0:
                status[idx]=1;masks[idx]&=~(1<<j)
                assert int(masks[idx]).bit_count()==2
            else:status[idx]=2;masks[idx]=0
            masks[index[q]] &= ~(1<<((j+2)%4))
            y=q;back=(j+2)%4
    result=dict(trails=trails,steps=steps,passages=len(records),distinct_catalogue_classes=len(keys),uncovered=failures,
                straight=sum(tuple(r['out'])==(0,1) for r in records),turning=sum(tuple(r['out'])!=(0,1) for r in records),seed=seed,box=BOX)
    dump('data/actual_generation.json',result)
    (ROOT/'data/actual_passages.jsonl').write_text(''.join(json.dumps(r)+'\n' for r in records))
    return records,result

def sample_record(record,ns,rng,stats):
    import ast
    outside={};pins={};pin_count=0;spin_count=0
    hemisphere=np.flatnonzero(SPINS[:12]@SPINS[0]>.1)
    def val(req):
        nonlocal pin_count,spin_count
        kind=req[0]
        if kind=='zero':return np.zeros((ns,3))
        if kind=='pin':
            key=str(req[1:]);pin_count+=ns
            if key not in pins:pins[key]=unit(rng,(ns,))
            return pins[key]
        key=tuple(req[1]);spin_count+=ns
        if key not in outside:
            ix=rng.choice(hemisphere,size=ns)
            if req[2]==1:ix[rng.random(ns)<.4]=12
            outside[key]=SPINS[ix]
        return outside[key]
    g={};e={edge(tuple(a),tuple(b)) for a,b in record['edges']}
    for xx,v in record['graph'].items():
        x=ast.literal_eval(xx);g[x]={k:v[k] for k in ('law','mark','out','tiponly_d')};g[x]['fields']=[];g[x]['values']=[]
        for request in v['requests']:
            if request['kind']=='field':r=F(1);m=val(request['request'])
            else:
                r=F(3,5)
                if request['law']=='x':m=np.zeros((ns,3));A=np.ones(ns)
                else:A,m,_=one_site(request['law'],[val(q) for q in request['requests']],ns)
                record_mean(stats,'actual_tip',request['law'],[F(1)]*len(request['requests']),r,m,A,record['pid'])
            g[x]['fields'].append(r);g[x]['values'].append(m)
    stats['actual_pin_fields']=stats.get('actual_pin_fields',0)+pin_count
    stats['actual_outside_fields']=stats.get('actual_outside_fields',0)+spin_count
    return g,e,tuple(record['out'])

def run_actual_chunk(records,ns,seed):
    stats=new_stats();t0=time.monotonic()
    for record in records:
        pid=record['pid'];rng=np.random.default_rng(seed+pid*104729);g,e,out=sample_record(record,ns,rng,stats)
        val=evaluate_graph(g,e,ns);rat=val[:,0]/val[:,1];c=.961 if out==(0,1) else .935
        stats['original_samples']+=ns;stats['original_failures']+=int(np.sum(rat<c-2e-12))
        stats['minimum_original_margin']=min(stats['minimum_original_margin'],float(rat.min()-c))
        if float(rat.min())<stats['minimum_original_ratio']:
            b=int(np.argmin(rat));stats['minimum_original_ratio']=float(rat[b]);stats['worst_original']=dict(pid=pid,catalogue_pid=record['catalogue_pid'],sample=b,ratio=float(rat[b]),threshold=c,margin=float(rat[b]-c),
                out=list(out),site=record['site'],configuration={str(x):dict(law=v['law'],fields=[a[b].tolist() for a in v['values']]) for x,v in g.items()},bonds=[[list(a),list(b)] for a,b in sorted(e)])
        passage_identity(g,e,out,stats);reduce_numeric(g,e,out,ns,stats,pid,rng)
    stats['seconds']=time.monotonic()-t0
    return stats

if __name__=='__main__':
    ap=argparse.ArgumentParser();ap.add_argument('--passages',type=int,default=8192);ap.add_argument('--samples',type=int,default=32);ap.add_argument('--workers',type=int,default=2)
    ap.add_argument('--seed',type=int,default=20261118);args=ap.parse_args();t0=time.monotonic()
    records,gen=make_records(args.passages,args.seed);print(json.dumps(gen),flush=True)
    rows=[]
    with ProcessPoolExecutor(max_workers=args.workers) as pool,open(ROOT/'logs/actual_chunks.jsonl','w',buffering=1) as log:
        futures=[pool.submit(run_actual_chunk,records[j:j+100],args.samples,args.seed) for j in range(0,len(records),100)]
        for i,f in enumerate(as_completed(futures)):
            r=f.result();rows.append(r);log.write(json.dumps(r)+'\n');print(i+1,len(futures),r['minimum_original_ratio'],r['mean_failures'],r['mapping_failures'],r['final_failures'],flush=True)
    result=merge(rows);result.update(generation=gen,samples_per_passage=args.samples,wall_seconds=time.monotonic()-t0)
    dump('data/actual_trace_checks.json',result)
